theory.code:
Accept: application/json  -> Content-Type: application/json      {"id":1,"name":"Anna"}
Accept: text/csv           -> Content-Type: text/csv; charset=utf-8   id,name\n1,Anna
Accept: application/xml    -> (serwer NIE wspiera XML) -> 406 Not Acceptable

server.createContext("/users/1", exchange -> {
    String accept = exchange.getRequestHeaders().getFirst("Accept");
    if (accept != null && accept.contains("text/csv")) {
        respond(exchange, "text/csv; charset=utf-8", "id,name\n1,Anna");
    } else {
        respond(exchange, "application/json; charset=utf-8", "{\"id\":1,\"name\":\"Anna\"}");
    }
});

// Accept: text/plain;q=0.3, application/json;q=0.9, text/csv;q=0.5
// Klient: najbardziej preferuje JSON (0.9), potem CSV (0.5), na koncu zwykly tekst (0.3)
List<String> supportedByServer = List.of("application/json", "text/csv", "text/plain");

String chooseBestFormat(List<Map.Entry<String, Double>> clientPreferences) {
    return clientPreferences.stream()
        .sorted((a, b) -> Double.compare(b.getValue(), a.getValue())) // malejaco po "q"
        .map(Map.Entry::getKey)
        .filter(supportedByServer::contains) // TYLKO to, co serwer faktycznie wspiera
        .findFirst()
        .orElse(null); // brak wspolnego formatu -> 406, patrz sekcja NOTE
}

// ZLE: Accept jest CALKOWICIE ignorowany, zawsze zwracany ten sam format
server.createContext("/users/1", exchange -> {
    respond(exchange, "application/json", "{\"id\":1,\"name\":\"Anna\"}"); // zawsze JSON, bez wzgledu na Accept
});

// DOBRZE: rzeczywista negocjacja, jawny 406 gdy brak wspolnego formatu
server.createContext("/users/1", exchange -> {
    String accept = exchange.getRequestHeaders().getFirst("Accept");
    if (accept == null || accept.contains("application/json") || accept.contains("*/*")) {
        respond(exchange, "application/json", "{\"id\":1,\"name\":\"Anna\"}");
    } else if (accept.contains("text/csv")) {
        respond(exchange, "text/csv", "id,name\n1,Anna");
    } else {
        exchange.sendResponseHeaders(406, -1); // brak wspolnego formatu
    }
});
